      "resolution": null,
      "anchors": [
        {"line_start": 177, "line_end": 177, "support": "mu/mu_c vs K_mu with fit mu = mu_c (1 + a_mu K_mu^{1/2})"},
        {"line_start": 248, "line_end": 248, "support": "mu_c = 0.30 ± 0.02 at jamming"}
