  ],
  "claims": [
    {
      "claim_id": "r_vs_St_muf015",
      "statement": "For the reference interparticle friction mu_f=0.15, the normalized friction r = mu/mu_c as a function of Stokes number St is given by r(St) = 1 + a_mu * sqrt(K_mu(St)), where K_mu(St) = K_phi * (1 + alpha_mu * St) / (1 + 0.1 * St) with K_phi = 0.065, a_mu = 14.3, and alpha_mu = 0.029.",
