          "args": [
            {"param": "one"},
            {
              "op": "multiply",
              "args": [
                {"param": "a_mu_muf015"},
                {
                  "op": "power",
                  "args": [
                    {
                      "op": "divide",
                      "args": [
                        {
                          "op": "multiply",
                          "args": [
                            {"param": "K_phi_common"},
                            {
                              "op": "add",
                              "args": [
