  ],
  "source_ambiguities": [
    {
      "ambiguity_id": "alpha_mu_values",
      "statement": "The paper reports alpha_mu = 0.029 for mu_f=0.15 in the main text (line 252) and in Table 1 (line 358). However, the abstract and introduction mention alpha_mu = 0.0088 for the experiments of Tapia et al. (line 133). The numerical value for the reference case is 0.029, which is used here.",
